@Transactional
public Order refund(long id, double amount) {
  Order order = get(id);
  if (order.status() != OrderStatus.PAID && order.status() != OrderStatus.SHIPPED) {
    throw new InvalidStateException("Only paid or shipped orders can be refunded");
  }
  if (amount <= 0 || amount > order.totalAmount().doubleValue()) {
    throw new IllegalArgumentException("Refund amount out of range");
  }
  repository.addRefund(id, amount);
  log.info("Order refunded: orderId={}", id);
  return order;
}

